import{_ as s,r as i,o as l,c,e as t,a as e,d as n,s as d}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Configuration - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Environment Configuration","slug":"environment-configuration","link":"#environment-configuration","children":[{"level":3,"title":"Specific Environment Files","slug":"specific-environment-files","link":"#specific-environment-files","children":[]}]},{"level":2,"title":"Application Configuration","slug":"application-configuration","link":"#application-configuration","children":[{"level":3,"title":"Debug Mode","slug":"debug-mode","link":"#debug-mode","children":[]},{"level":3,"title":"Safe Mode","slug":"safe-mode","link":"#safe-mode","children":[]},{"level":3,"title":"CSRF protection","slug":"csrf-protection","link":"#csrf-protection","children":[]}]}],"relativePath":"2.x/setup/configuration.md","filePath":"2.x/setup/configuration.md"}'),p={name:"2.x/setup/configuration.md"};function f(u,o,h,m,g,v){const a=i("pre-heading"),r=i("post-heading");return l(),c("div",null,[t(a),o[0]||(o[0]=e("h1",null,"Configuration",-1)),t(r),o[1]||(o[1]=e("p",null,[n("All of the configuration files for October CMS are stored in the "),e("strong",null,"config"),n(" directory. Each option is documented, so feel free to look through the files and get familiar with the options available to you.")],-1)),o[2]||(o[2]=e("p",null,[e("a",{id:"oc-environment-configuration"})],-1)),o[3]||(o[3]=e("h2",{id:"environment-configuration"},[e("a",{href:"#environment-configuration",class:"header-anchor"},"#"),n(" Environment Configuration")],-1)),o[4]||(o[4]=e("p",null,[n("It is often helpful to have different configuration values based on the environment the application is running in. To control confguration in different environments, October CMS uses a "),e("a",{href:"https://github.com/vlucas/phpdotenv",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("DotEnv library"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),e("span",{class:"sr-only"},"(opens new window)")])]),n(" to make it easy to manage environment variables. These variables can override any values specified in the "),e("strong",null,"config"),n(" directory.")],-1)),o[5]||(o[5]=d(`<p>In a fresh installation of October CMS, the base directory will contain a <code>.env.example</code> file that provides typical values for a local environment. During the installation process, this file will be copied to <code>.env</code> where you can make any changes.</p><p>For example, the database connection can be specified with these variables.</p><pre><code>DB_CONNECTION=mysql
DB_HOST=127.0.0.1
DB_PORT=3306
DB_DATABASE=database
DB_USERNAME=root
DB_PASSWORD=
</code></pre><p>Any variable in your <code>.env</code> file can be overridden by external environment variables such as server-level or system-level environment variables. For example, in Apache this line can be added to the <code>.htaccess</code> or <code>httpd.config</code> file:</p><pre><code>SetEnv DB_CONNECTION &quot;mysql&quot;
</code></pre><p>To recap, configuration values are loaded in this order.</p><ol><li>System environment variables</li><li>Variables in the <code>.env</code> file</li><li>Values in the <strong>config</strong> PHP files</li></ol><blockquote><p><strong>Important</strong>: Never commit your <code>.env</code> file to source control because this would be a security risk in the event an intruder gains access to your source control repository, since any sensitive credentials would get exposed.</p></blockquote><h3 id="specific-environment-files"><a href="#specific-environment-files" class="header-anchor">#</a> Specific Environment Files</h3><p>In rare cases you may need to load different <code>.env</code> files for the same codebase, such as local, staging and production. The current application environment detection can be overridden by a server-level <code>APP_ENV</code> environment variable.</p><pre><code>SetEnv APP_ENV &quot;staging&quot;
</code></pre><p>The above example sets the <code>APP_ENV</code> value to <strong>staging</strong> will therefore attempt to load values from the <code>.env.staging</code> file instead.</p><h2 id="application-configuration"><a href="#application-configuration" class="header-anchor">#</a> Application Configuration</h2><p>Here we will cover some common configuration items and their purpose.</p><p><a id="oc-debug-mode"></a></p><h3 id="debug-mode"><a href="#debug-mode" class="header-anchor">#</a> Debug Mode</h3><p>The debug setting is found in the <code>config/app.php</code> configuration file with the <code>debug</code> parameter. By default, this option looks at the value of the <code>APP_DEBUG</code> environment variable, which is stored in your <code>.env</code> file.</p><pre><code>APP_DEBUG=true
</code></pre><p>When enabled, this setting will show detailed error messages when they occur along with other debugging features. While useful during development, debug mode should always be disabled when used in a live production site. This prevents potentially sensitive information from being displayed to the end-user.</p><p>The debug mode uses the following features when enabled:</p><ol><li><a href="./../cms/pages.html#oc-error-page">Detailed error pages</a> are displayed.</li><li>Failed user authentication provides a specific reason.</li><li><a href="./../markup/filter-theme.html">Combined assets</a> are not minified by default.</li><li><a href="#oc-safe-mode">Safe mode</a> is disabled by default.</li></ol><blockquote><p><strong>Important</strong>: Always set the <code>APP_DEBUG</code> setting to <code>false</code> in production environments.</p></blockquote><p><a id="oc-safe-mode"></a></p><h3 id="safe-mode"><a href="#safe-mode" class="header-anchor">#</a> Safe Mode</h3><p>The safe mode setting is found in the <code>config/cms.php</code> configuration file with the <code>enable_safe_mode</code> parameter. By default, the option sources its value from <code>CMS_SAFE_MODE</code> which can be added to your <code>.env</code> file.</p><pre><code>CMS_SAFE_MODE=null
</code></pre><p>When safe mode is enabled, the PHP code section is disabled in CMS templates to prevent a user from potentially executing malicious code.</p><p>This variable can be set to <code>true</code> or <code>false</code>. If set to <code>null</code>, safe mode will activate when <a href="#oc-debug-mode">debug mode</a> is disabled.</p><p><a id="oc-csrf-protection"></a></p><h3 id="csrf-protection"><a href="#csrf-protection" class="header-anchor">#</a> CSRF protection</h3><p>October CMS provides an easy method of protecting your application from cross-site request forgeries. First a random token is placed in your user&#39;s session. Then when a <a href="./../services/html.html#oc-form-tokens">opening form tag is used</a> the token is added to the page and submitted back with each request.</p><pre><code>ENABLE_CSRF=true
</code></pre><p>While CSRF protection is enabled by default, you can disable it with the <code>enable_csrf_protection</code> parameter in the <code>config/system.php</code> configuration file, or the sourced value from <code>ENABLE_CSRF</code> environment variable.</p>`,33))])}const _=s(p,[["render",f]]);export{y as __pageData,_ as default};
